import React, { useState, useEffect } from 'react';
import PlayerRow from './PlayerRow';
import ChampionsLeagueFooter from './ChampionsLeagueFooter';
import ChampionsLeagueHeader from './ChampionsLeagueHeader';

const ChampionsLeagueScorers = () => {
  const [players, setPlayers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeModal, setActiveModal] = useState(null);
  const [modalData, setModalData] = useState(null);

  useEffect(() => {
    setIsLoading(true);

    fetch('/data/top-champions-league-scorers.json')
      .then(response => {
        if (!response.ok) {
          throw new Error('Error al cargar los datos de los goleadores');
        }
        return response.json();
      })
      .then(data => {
        const formattedPlayers = data.map((player, index) => ({
          position: index + 1,
          name: player.nombre,
          team: player.equipos.map(t => t.equipo).join('/'),
          goals: player.goles_totales,
          fullData: player
        }));
        setPlayers(formattedPlayers);
        setIsLoading(false);
      })
      .catch(err => {
        console.error('Error fetching data:', err);
        setError(err.message);
        setIsLoading(false);
      });
  }, []);

  const showTeamsModal = (player) => {
    if (!player || !player.fullData || !player.fullData.equipos) {
      console.error('Datos de jugador incompletos:', player);
      return;
    }

    setModalData({
      title: `Equipos de ${player.name}`,
      content: player.fullData.equipos
    });
    setActiveModal('teams');
  };

  const showPlayerInfoModal = (player) => {
    if (!player || !player.fullData) {
      console.error('Datos de jugador incompletos:', player);
      return;
    }

    setModalData({
      title: `Información de ${player.name}`,
      player: player.fullData
    });
    setActiveModal('playerInfo');
  };

  const showSeasonsModal = (player) => {
    if (!player || !player.fullData) {
      console.error('Datos de jugador incompletos:', player);
      return;
    }

    setModalData({
      title: `Mejor temporada de ${player.name}`,
      season: player.fullData.temporada_max_goles,
      goals: player.fullData.max_goles_temporada,
      player: player.name
    });
    setActiveModal('seasons');
  };

  const closeModal = () => {
    setActiveModal(null);
    setModalData(null);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center">
          <div className="w-32 h-32 mx-auto mb-6 rounded-xl shadow-lg p-2 border border-champions-gold/30 bg-champions-blue/80">
            <img 
              src="/images/logos/cc.png" 
              alt="Champions League Logo" 
              className="w-full h-full object-contain animate-pulse"
            />
          </div>
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-champions-gold mx-auto"></div>
          <p className="mt-4 text-lg text-white">
            <span className="champions-star">★</span> Cargando goleadores <span className="champions-star">★</span>
          </p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-champions-blue">
        <div className="text-center text-red-500">
          <p className="text-2xl font-bold text-white">Error al cargar los datos</p>
          <p className="mt-2 text-champions-gold">{error}</p>
        </div>
      </div>
    );
  }

  const Modal = ({ isOpen, onClose, children }) => {
    if (!isOpen) return null;

    return (
      <div className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-60">
        <div className="bg-white rounded-lg shadow-lg p-6 max-w-md w-full m-4 transform transition-all animate-fadeIn">
          <div className="flex justify-end">
            <button 
              onClick={onClose}
              className="text-gray-500 hover:text-champions-blue"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
          {children}
        </div>
      </div>
    );
  };

  const renderTeamsModal = () => (
    <Modal isOpen={activeModal === 'teams'} onClose={closeModal}>
      <h2 className="text-xl font-bold text-champions-blue mb-4 border-b border-gray-200 pb-2">
        {modalData?.title || 'Equipos'}
      </h2>
      <div className="space-y-4">
        {modalData?.content && modalData.content.map((team, idx) => (
          <div key={idx} className="flex justify-between items-center p-3 bg-gray-50 rounded-lg">
            <div className="font-medium">{team.equipo}</div>
            <div className="flex items-center">
              <span className="text-champions-gold font-bold mr-1">⚽</span>
              <span className="font-bold text-champions-blue">{team.goles}</span>
            </div>
          </div>
        ))}
      </div>
    </Modal>
  );

  const renderPlayerInfoModal = () => (
    <Modal isOpen={activeModal === 'playerInfo'} onClose={closeModal}>
      <h2 className="text-xl font-bold text-champions-blue mb-4 border-b border-gray-200 pb-2">
        {modalData?.title || 'Información del Jugador'}
      </h2>
      {modalData?.player && (
        <div className="space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="text-gray-600">Nacionalidad:</div>
            <div className="font-medium">{modalData.player.nacionalidad}</div>

            <div className="text-gray-600">Fecha de Nacimiento:</div>
            <div className="font-medium">{modalData.player.fecha_nacimiento}</div>

            <div className="text-gray-600">Goles Totales:</div>
            <div className="font-medium text-champions-blue font-bold">{modalData.player.goles_totales}</div>

            <div className="text-gray-600">Mejor Temporada:</div>
            <div className="font-medium">{modalData.player.temporada_max_goles} ({modalData.player.max_goles_temporada} goles)</div>
          </div>
        </div>
      )}
    </Modal>
  );

  const renderSeasonsModal = () => (
    <Modal isOpen={activeModal === 'seasons'} onClose={closeModal}>
      <h2 className="text-xl font-bold text-champions-blue mb-4 border-b border-gray-200 pb-2">
        {modalData?.title || 'Mejor Temporada'}
      </h2>
      {modalData && (
        <div className="p-4 bg-gray-50 rounded-lg">
          <p className="mb-2 text-lg font-medium">Temporada: <span className="text-champions-blue">{modalData.season}</span></p>
          <div className="flex items-center">
            <span className="text-champions-gold text-lg mr-2">⚽</span>
            <span className="text-2xl font-bold text-champions-blue">{modalData.goals}</span>
            <span className="ml-2 text-gray-600">goles</span>
          </div>
          <p className="mt-4 text-gray-600 italic">
            Esta fue la mejor temporada goleadora para {modalData.player} en la Champions League.
          </p>
        </div>
      )}
    </Modal>
  );

  return (
    <div className="min-h-screen flex flex-col">
      <ChampionsLeagueHeader 
        onTeamsClick={(player) => showTeamsModal(player)}
        onSeasonsClick={(player) => showSeasonsModal(player)}
        players={players}
      />

      <main className="flex-grow py-8">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="glass-effect rounded-lg overflow-hidden shadow-lg">
            <div className="p-6 bg-champions-blue text-white relative overflow-hidden">
              <div className="absolute top-0 right-0 opacity-10 w-64 h-64">
                {Array(5).fill('').map((_, i) => (
                  <div key={i} 
                    className="absolute text-champions-gold"
                    style={{
                      fontSize: `${Math.random() * 20 + 20}px`,
                      top: `${Math.random() * 100}%`,
                      left: `${Math.random() * 100}%`,
                      opacity: Math.random() * 0.5 + 0.2,
                      transform: `rotate(${Math.random() * 360}deg)`
                    }}
                  >★</div>
                ))}
              </div>

              <div className="flex items-center mb-4">
                <div className="w-16 h-16 mr-4 overflow-hidden rounded-lg shadow-md border border-champions-gold/30 bg-champions-blue/70">
                  <img 
                    src="/images/logos/cc.png" 
                    alt="Champions League Logo" 
                    className="w-full h-full object-contain transform hover:scale-105 transition-transform duration-300"
                  />
                </div>
                <h1 className="text-3xl font-bold">
                  Máximos Goleadores de la UEFA Champions League
                </h1>
              </div>
              <p className="mt-2 text-blue-100">
                <span className="trophy-icon">🏆</span> 
                Histórico de jugadores con más goles en la competición
              </p>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-100">
                  <tr>
                    <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Pos</th>
                    <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Jugador</th>
                    <th className="py-3 px-4 text-left text-xs font-medium text-champions-blue uppercase tracking-wider">Equipos</th>
                    <th className="py-3 px-4 text-center text-xs font-medium text-champions-blue uppercase tracking-wider">
                      <span className="flex items-center justify-center">
                        <span className="trophy-icon text-lg">⚽</span> Goles
                      </span>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {players.map((player) => (
                    <PlayerRow
                      key={player.position}
                      position={player.position}
                      name={player.name}
                      team={player.team}
                      goals={player.goals}
                      fullData={player.fullData}
                      onPlayerInfoClick={() => showPlayerInfoModal(player)}
                    />
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </main>

      {renderTeamsModal()}
      {renderPlayerInfoModal()}
      {renderSeasonsModal()}

      <ChampionsLeagueFooter />
    </div>
  );
};

export default ChampionsLeagueScorers;
